def _record_degraded_gate(gate: str, reason: str) -> str:
    """登记一次门禁降级并返回人类可读的降级标记 (E4: 让盲区可见)。

    静默降级会让复核者以为门禁真的跑过; 这里把"哪个门禁降级了、为什么、
    因此少校验了什么"写进 ``DEGRADE_LOG``, 回归测试再断言日志内容 ——
    删掉降级分支、改写理由或把降级藏进别的路径都会在此变红。

    Args:
        gate: 降级的门禁名 (如 ``"G1 locked_counts"``)。
        reason: 降级理由 (必须点明缺失的事实源与少校验的内容)。

    Returns:
        形如 ``DEGRADED[<gate>]: <reason>`` 的标记串, 供调用方就地断言。
    """
    marker = f"DEGRADED[{gate}]: {reason}"                                                         # 降级标记文本: 让人一眼看出是哪道门在放水
    DEGRADE_LOG.append({"gate": gate, "reason": reason, "marker": marker})  # 三字段同记: 门禁名、理由、可读标记, 少一个复核者就判不出丢的是什么
    return marker


def test_gen_ledger_file_is_wellformed():
    """台账文件本身结构完好: schema 版本、基准线、locked_counts 键集齐备。

    独立交付 (无 ASSET-TRUTH-LEDGER.json) 时平滑降级为校验本地
    manifest.yaml — 但 manifest 缺失即判失败, 不允许「什么都不校验就过」。
    """
    if not LEDGER_PATH.is_file():  # 台账在位才走计数校验: 缺台账是合法交付形态, 降级而非硬失败
        # 独立交付平滑降级: 校验本地 manifest.yaml 与本地资产基线
        assert MANIFEST_PATH.is_file(), "manifest.yaml 缺失 (本地资产基线)"                          # manifest 缺失即红: 没有基线就无从谈资产守恒
        mdata = yaml.safe_load(MANIFEST_PATH.read_text(encoding="utf-8"))                           # 按 YAML 读 manifest
        assert mdata.get("name") == SKILL                                                           # 归属名必须与 skill 键一致
        return
    data = yaml.safe_load(LEDGER_PATH.read_text(encoding="utf-8"))                                  # 读台账: 锁定计数的权威来源
    assert data["schema"] == "asset-truth-ledger-v1"                                            # schema 串钉版本: 换格式不换值会让旧结构被当新结构读
    assert data["plan_targets"] == PLAN_TARGETS                                             # 计划目标必须逐项相等: 台账与计划脱节就失去了守恒的意义
    assert set(data["locked_counts"]) >= {"tests", "templates", "evals", "contracts", "total"}  # 超集判定: 多带新维度合法, 少一维才是损坏


def test_gen_ledger_lock_matches_plan_targets():
    """G1 资产守恒门禁: locked_counts 相对计划基准线只增不减 (fail-closed)。

    守住的是「删测试文件拉低 tests 计数」这类资产流失 — 预提交钩子必须拒绝。
    台账 notes 已声明: 并行抢救资产晚到导致的计数上升属预期 (contracts
    955->998), 无需回退; 而任何未登记的下降都必须 fail。
    """
    # G1 门禁语义: 台账 locked_counts 相对计划基准线只增不减 (Fail-Closed)。
    # 台账 notes 声明: 并行抢救资产晚到导致计数上升属预期 (contracts 955->998),
    # 无需回退; 已批准并记录的偏差 (APPROVED_DEFICITS, 见上) 除外, 故此处断言
    # deficits ⊆ APPROVED_DEFICITS 而非 ==。
    if not LEDGER_PATH.is_file():                                                                 # 台账缺失即降级: 独立交付模式下没有仓级台账
        # 独立交付平滑降级路径 (E4 显式化): 此处**不校验任何计数**, 只校验
        # 目录存在性 —— G1 资产守恒在本场景下是空门禁。必须登记降级痕迹并
        # 就地断言标记, 让"这条路径没有计数守恒保护"可见; 独立交付没有台账
        # 是合法的, 故保持降级而不改成硬失败。
        marker = _record_degraded_gate(  # 降级必须留下可断言的痕迹: 直接 return 的话, 盲区不会被任何人看见
            "G1 locked_counts",                                                                     # 报出是哪条门在降级
            f"{LEDGER_PATH.name} 缺失 (独立交付模式): 降级为 contracts/ 与 test/ "                             # 写清降级到什么程度: 让人知道哪些校验没跑
            f"目录存在性检查, 不校验任何资产计数")                                                                # 强调不校验计数: 否则会被误读成"仍然在守"
        assert marker.startswith("DEGRADED[G1 locked_counts]"), marker  # 就地断言标记: 登记与断言同在一条用例里, 删掉登记就当场红
        assert (SKILL_DIR / "contracts").is_dir(), "contracts/ 目录缺失"                                # 契约目录必须在
        assert (SKILL_DIR / "test").is_dir(), "test/ 目录缺失"                                          # 测试目录必须在
        return
    data = yaml.safe_load(LEDGER_PATH.read_text(encoding="utf-8"))                                  # 台账在: 走严格路径
    if data["locked"]:  # locked=False 表示台账尚未 relock: 此时不判守恒, 免得误报
        locked = {k: data["locked_counts"][k] for k in PLAN_TARGETS}                                # 只取计划目标覆盖到的键
        deficits = {k: (PLAN_TARGETS[k] - locked[k]) for k in PLAN_TARGETS if locked[k] < PLAN_TARGETS[k]}  # 算差值: 低于基准线才是资产流失
        # 超白名单额度的下降 = 未批准资产流失, 必须 fail-closed
        unapproved = {k: v for k, v in deficits.items() if v > APPROVED_DEFICITS.get(k, 0)}  # 超额度才算流失: 批准过的删除不该反复报
        assert not unapproved, f"台账锁定值低于计划基准线且无批准记录 (资产流失): {unapproved}"                          # 无批准记录的流失即红: 已知流失要显式登记
        # 白名单外的键 (例如新出现的 scripts:N) 同样视为未登记偏差
        assert deficits.keys() <= APPROVED_DEFICITS.keys(), f"未登记的基准偏差: {deficits}"  # 白名单外的键同样算未登记偏差: 新维度冒出来也得有人签字
        # total 必须与分类计数自洽, 防止台账被手工改坏一处而不被察觉
        assert locked["total"] == sum(                                                              # 总数必须等于分类之和
            v for k, v in locked.items() if k != "total"), "total 与分类计数不一致"                       # 排除 total 自身再求和, 否则自我循环


class TestLedgerDegradedPath:
    """E4: 独立交付模式 (无 ASSET-TRUTH-LEDGER.json) 的降级路径必须显式可见。

    独立交付没有仓库级台账是**合法**场景, 所以这里不把降级改成硬失败;
    要保证的是"降级被登记、被断言", 复核者一眼能看出本场景下 G1 计数守恒
    没有被校验, 而不是看到一片静默的绿。
    """

    def test_degraded_path_is_explicitly_marked(self, tmp_path, monkeypatch):
        """台账缺失时必须登记降级标记, 且标记点名门禁名与缺失的台账文件。

        标记必须点名到具体台账文件: 只记一句"已降级"的话, 复核者无法判断
        丢的是哪一份证据, 于是降级会在一次次重复里被当成常态接受下来。
        """
        # 指向一个必定不存在的台账: 强制走独立交付降级分支
        monkeypatch.setattr(sys.modules[__name__], "LEDGER_PATH",                                   # 注入临时台账路径: 不碰真实台账
                            tmp_path / "ASSET-TRUTH-LEDGER.json")                                   # 指向临时区里的文件
        DEGRADE_LOG.clear()                                           # 先清空: 上一条用例的降级记录会串进这条的条数断言
        test_gen_ledger_lock_matches_plan_targets()                   # 直接调被测函数: 降级发生在函数内部, 走 pytest 入口会掩盖它
        assert len(DEGRADE_LOG) == 1, f"降级未被登记或登记了多次: {DEGRADE_LOG}"  # 恰好一条: 登记两次说明降级路径被走了两遍, 计数守恒彻底没跑
        entry = DEGRADE_LOG[0]                                                                      # 取第一条降级记录
        assert entry["gate"] == "G1 locked_counts", entry                                           # 门名必须对得上
        assert "ASSET-TRUTH-LEDGER.json" in entry["reason"], entry                                  # 理由里要点出台账文件名
        assert "不校验任何资产计数" in entry["reason"], entry                                                # 理由里要点明降级到什么程度
        assert entry["marker"].startswith("DEGRADED[G1 locked_counts]"), entry                     # 标记前缀必须带门名: 解析标记的人靠它定位

    def test_present_ledger_still_fails_closed(self, tmp_path, monkeypatch):
        """台账在位但计数低于基准线时门禁必须 fail-closed (降级不是逃生门)。"""
        bad = tmp_path / "ASSET-TRUTH-LEDGER.json"                                                  # 造一份"计数不足"的台账
        bad.write_text(yaml.safe_dump({                                                             # 坏台账落在临时区
            "schema": "asset-truth-ledger-v1",                                                      # schema 标识
            "plan_targets": PLAN_TARGETS,                                                           # 计划目标照抄
            "locked": True,                                                                         # 锁定标志
            # tests 比基准线低 50, 远超 APPROVED_DEFICITS 批准的 8
            "locked_counts": {**PLAN_TARGETS, "tests": PLAN_TARGETS["tests"] - 50},               # 测试计数故意少 50: 制造无批准记录的流失
        }), encoding="utf-8")
        monkeypatch.setattr(sys.modules[__name__], "LEDGER_PATH", bad)                              # 注入坏台账路径
        DEGRADE_LOG.clear()                                                                      # 清空降级日志: 前面的用例留下的记录会干扰这条
        with pytest.raises(AssertionError):  # 台账在位必须抛 AssertionError: 降级是缺台账专属, 不是逃生门
            test_gen_ledger_lock_matches_plan_targets()
        assert DEGRADE_LOG == [], "台账在位时不得登记降级 (降级只属于缺台账场景)"  # 在位时不得留下降级记录: 有记录就说明有人把降级混进了正常路径
